public static METSalesOrderExtractionExportService construct()
{
    return new METSalesOrderExtractionExportService();
}

public container parmSelectedExtractionIds(container _ids = selectedExtractionIds)
{
    selectedExtractionIds = _ids;
    return selectedExtractionIds;
}

public void run()
{
    METSalesOrderExtractionExportIntegration    exportIntegration;
    DEVIntegMessagesLoadBaseType                loadType;
    DEVIntegExportDocumentLog                   exportDocumentLog;
    METSalesOrderExtractionTable                header;
    int                                         idx;

    exportIntegration = METSalesOrderExtractionExportIntegration::construct();

    if (!exportIntegration.isMessageTypeEnabled())
    {
        throw error("Export message type is not configured or enabled. Set up METSalesOrderExtractionExportIntegration in DEV External Integration.");
    }

    loadType = DEVIntegMessagesLoadBaseType::constructFromMessageTypeOutbound(exportIntegration.parmMessageTypeTableOutbound());

    for (idx = 1; idx <= conLen(selectedExtractionIds); idx++)
    {
        METSalesOrderExtractionId extractionId = conPeek(selectedExtractionIds, idx);
        header = METSalesOrderExtractionTable::find(extractionId);

        if (!header.RecId || header.Exported == NoYes::Yes)
        {
            continue;
        }

        exportIntegration.insertFromMETSalesOrderExtractionTable(header);

        exportDocumentLog = DEVIntegExportDocumentLog::findFromCommon(header, exportIntegration.exportClassName());
        if (exportDocumentLog.RecId)
        {
            exportIntegration.exportFileMessage(exportDocumentLog, loadType);
            this.updateExportStatus(extractionId);
        }
    }
}

protected void updateExportStatus(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionTable header;

    ttsbegin;
    header = METSalesOrderExtractionTable::find(_extractionId, true);
    if (header.RecId)
    {
        header.Exported         = NoYes::Yes;
        header.ExportedDateTime = DateTimeUtil::utcNow();
        header.update();
    }
    ttscommit;  
}
